Here is the commit message:
accel/ivpu: Add buffer overflow check in MS get_info_ioctl

Add validation that the info size returned from the metric stream info
query is not exceeded when checked against the allocated buffer size.
If the firmware returns a size larger than the buffer, reject the
operation with -EOVERFLOW instead of proceeding with an incorrect
buffer copy.

Fixes: cdfad4db7756 ("accel/ivpu: Add NPU profiling support")
Cc: stable@vger.kernel.org # v6.18+
Signed-off-by: Andrzej Kacprowski <andrzej.kacprowski@linux.intel.com>
Reviewed-by: Karol Wachowski <karol.wachowski@linux.intel.com>
Signed-off-by: Karol Wachowski <karol.wachowski@linux.intel.com>
Link: https://patch.msgid.link/20260529120841.135852-1-andrzej.kacprowski@linux.intel.com

Here is the root cause:
The driver in `ivpu_ms_get_info_ioctl` trusts the `info_size` returned from the firmware without validating that it does not exceed the size of the internally allocated buffer (`bo`), which could lead to a buffer overflow when copying metric stream info data.

Here is the patch:

 int ivpu_ms_get_info_ioctl(struct drm_device *dev, void *data, struct drm_file *file)
 {
 	struct drm_ivpu_metric_streamer_get_data *args = data;
 	struct ivpu_file_priv *file_priv = file->driver_priv;
 	struct ivpu_device *vdev = file_priv->vdev;
 	struct ivpu_bo *bo;
 	u64 info_size;
 	int ret;

 	if (!args->metric_group_mask)
 		return -EINVAL;

 	if (!args->buffer_size)
 		return ivpu_jsm_metric_streamer_info(vdev, args->metric_group_mask,
 						     0, 0, NULL, &args->data_size);
 	if (!args->buffer_ptr)
 		return -EINVAL;

 	mutex_lock(&file_priv->ms_lock);

 	bo = get_ms_info_bo(file_priv);
 	if (!bo) {
 		ret = -ENOMEM;
 		goto unlock;
 	}

 	ret = ivpu_jsm_metric_streamer_info(vdev, args->metric_group_mask, bo->vpu_addr,
 					    ivpu_bo_size(bo), NULL, &info_size);
 	if (ret)
 		goto unlock;

+	if (info_size > ivpu_bo_size(bo)) {
+		ivpu_warn_ratelimited(vdev, "MS info overflow: %#llx > %#zx\n",
+				      info_size, ivpu_bo_size(bo));
+		ret = -EOVERFLOW;
+		goto unlock;
+	}
+
 	if (args->buffer_size < info_size) {
 		ret = -ENOSPC;
 		goto unlock;
 	}

 	if (copy_to_user(u64_to_user_ptr(args->buffer_ptr), ivpu_bo_vaddr(bo), info_size))
 		ret = -EFAULT;

 	args->data_size = info_size;
 unlock:
 	mutex_unlock(&file_priv->ms_lock);

 	return ret;
 }



